SBB_AB	MACRO ACC, REG	MVI	A,{ACC}	MVI	B,{REG}	SBB	B	ENDMSUB_AB	MACRO ACC, REG	MVI	A,{ACC}	MVI	B,{REG}	SUB	B	ENDMSTACK EQU 1F00H	ORG	0400H	LXI	D,STACK	LXI	SP,STACK+1 ; Set it 1 higher as it first decreases before pushing data there	MVI	A,00H	MVI	C,0FFH	MVI	B,04HLOOP:			; Clean up of stack space	STAX	D	DCX	D	DCR	C	JNZ	LOOP	MVI	C,0FFH	DCR	B	JNZ	LOOP	MVI	B,0FFHCODE_BEG:			; Here is actual code	STC;	CMC	LXI	D,1234h	LXI	H,5678H	PUSH	D	XTHL	PUSH	H	HLT	MOV	A,B	PUSH	PSW		DCR	B	JNZ	CODE_BEG	HLTQUIT:			; We can quit here	HLTNEXT:	MVI	A,0AAH	PUSH	PSW	HLT	; Some data goes here	DATA:	DB	55H, 0AAH, 10H, 05H, 55H, 09H, 99H, 0FFH;DATA:	DB	00H, 1FH, 0FH, 10H, 01H, 0FFH	END